Veo la función. El problema de rendimiento de **9.86 segundos** probablemente se debe a varios factores en la conexión WebSocket. Analicemos:

## Problemas identificados

1. **Sin timeout de conexión**: Pusher intenta conectar indefinidamente si el servidor no responde rápido.
2. **`forceTLS: false`**: En producción con HTTPS, esto puede causar intentos fallidos antes de usar TLS.
3. **Autenticación de canal privado**: El endpoint `/broadcasting-auth` puede ser lento.
4. **Sin conexión diferida**: Se ejecuta inmediatamente bloqueando el render.

## Soluciones propuestas

### Opción 1: Agregar timeouts y configuración optimizada (Recomendada)

```javascript
function configurarWebSocketNotificaciones() {
    try {
        if (!window.configuracion_reverbg) {
            return;
        }

        // Diferir la conexión para no bloquear el render inicial
        setTimeout(() => {
            const es_https = window.location.protocol === 'https:';

            const PUSHER = new Pusher(window.configuracion_reverbg.appKey, {
                wsHost: window.configuracion_reverbg.host,
                wsPort: window.configuracion_reverbg.port,
                wssPort: window.configuracion_reverbg.port,
                cluster: 'mt1',
                forceTLS: es_https, // Usar TLS según el protocolo actual
                enabledTransports: es_https ? ['wss'] : ['ws'], // Solo el transporte necesario
                disabledTransports: es_https ? ['ws'] : ['wss'],
                activityTimeout: 30000, // 30 segundos antes de considerar inactivo
                pongTimeout: 10000, // 10 segundos para esperar pong
                authEndpoint: '/broadcasting-auth',
                auth: {
                    headers: {
                        'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
                    }
                }
            });

            // Timeout manual para abortar si tarda demasiado
            const timeout_conexion = setTimeout(() => {
                if (PUSHER.connection.state !== 'connected') {
                    console.warn('⚠️ WebSocket: Timeout de conexión, desconectando...');
                    PUSHER.disconnect();
                }
            }, 5000); // 5 segundos máximo

            PUSHER.connection.bind('connected', function() {
                clearTimeout(timeout_conexion);
                suscribirCanal(PUSHER);
            });

            PUSHER.connection.bind('failed', function() {
                clearTimeout(timeout_conexion);
                console.error('❌ Conexión WebSocket falló');
            });

            PUSHER.connection.bind('error', function(error) {
                console.error('❌ Error de WebSocket:', error);
            });
        }, 100); // Pequeño delay para no bloquear el render

    } catch (error) {
        console.error('💥 Error en configurarWebSocketNotificaciones:', error);
    }
}

function suscribirCanal(pusher) {
    let usuario_id = window.configuracion_reverbg.usuario_id;
    if (!usuario_id) return;

    const NOMBRE_CANAL = `private-App.Models.Usuarios.User.${usuario_id}`;
    const CANAL = pusher.subscribe(NOMBRE_CANAL);

    CANAL.bind('pusher:subscription_error', function(error) {
        console.error('❌ Error al suscribirse al canal:', error);
    });

    CANAL.bind('Illuminate\\Notifications\\Events\\BroadcastNotificationCreated', function(data) {
        if (data.tipo === 'nueva_notificacion') {
            audio_notificacion.play();
            cargarNotificiacionesHeader();
        }
        if (data.tipo === 'nuevo_mensaje') {
            if (($('#soporte-guardado-id').val() == data.soporte_id) || ($('#soporte_empresa_id').val() == data.soporte_id)) {
                audio_notificacion.play();
                consultarChat(data.soporte_id);
            }
        }
    });
}
```

### Opción 2: Cargar solo cuando sea necesario (lazy loading)

```javascript
function configurarWebSocketNotificaciones() {
    if (!window.configuracion_reverbg) return;

    // Solo conectar cuando la página esté completamente cargada y el usuario interactúe
    if (document.readyState === 'complete') {
        requestIdleCallback(() => inicializarPusher(), { timeout: 2000 });
    } else {
        window.addEventListener('load', () => {
            requestIdleCallback(() => inicializarPusher(), { timeout: 2000 });
        });
    }
}
```

## Resumen de cambios clave

| Cambio | Impacto |
|--------|---------|
| `forceTLS: es_https` | Evita intentos fallidos de protocolo |
| `enabledTransports` dinámico | Solo usa el transporte correcto |
| `activityTimeout` / `pongTimeout` | Detecta conexiones muertas |
| `setTimeout` inicial | No bloquea el render |
| Timeout manual de 5s | Aborta si no conecta rápido |
| Suscripción después de `connected` | No suscribe hasta estar conectado |

¿Quieres que aplique la **Opción 1** al archivo?

## Solución optimizada (una sola función)

```javascript
function configurarWebSocketNotificaciones() {
    try {
        if (!window.configuracion_reverbg) {
            return;
        }

        // Diferir la conexión para no bloquear el render inicial
        setTimeout(() => {
            const es_https = window.location.protocol === 'https:';

            const PUSHER = new Pusher(window.configuracion_reverbg.appKey, {
                wsHost: window.configuracion_reverbg.host,
                wsPort: window.configuracion_reverbg.port,
                wssPort: window.configuracion_reverbg.port,
                cluster: 'mt1',
                forceTLS: es_https,
                enabledTransports: es_https ? ['wss'] : ['ws'],
                disabledTransports: es_https ? ['ws'] : ['wss'],
                activityTimeout: 30000,
                pongTimeout: 10000,
                authEndpoint: '/broadcasting-auth',
                auth: {
                    headers: {
                        'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
                    }
                }
            });

            // Timeout manual para abortar si tarda demasiado
            const timeout_conexion = setTimeout(() => {
                if (PUSHER.connection.state !== 'connected') {
                    console.warn('⚠️ WebSocket: Timeout de conexión, desconectando...');
                    PUSHER.disconnect();
                }
            }, 5000);

            PUSHER.connection.bind('connected', function() {
                clearTimeout(timeout_conexion);

                let usuario_id = window.configuracion_reverbg.usuario_id;
                if (!usuario_id) return;

                const NOMBRE_CANAL = `private-App.Models.Usuarios.User.${usuario_id}`;
                const CANAL = PUSHER.subscribe(NOMBRE_CANAL);

                CANAL.bind('pusher:subscription_error', function(error) {
                    console.error('❌ Error al suscribirse al canal:', error);
                });

                CANAL.bind('Illuminate\\Notifications\\Events\\BroadcastNotificationCreated', function(data) {
                    if (data.tipo === 'nueva_notificacion') {
                        audio_notificacion.play();
                        cargarNotificiacionesHeader();
                    }
                    if (data.tipo === 'nuevo_mensaje') {
                        if (($('#soporte-guardado-id').val() == data.soporte_id) || ($('#soporte_empresa_id').val() == data.soporte_id)) {
                            audio_notificacion.play();
                            consultarChat(data.soporte_id);
                        }
                    }
                });
            });

            PUSHER.connection.bind('failed', function() {
                clearTimeout(timeout_conexion);
                console.error('❌ Conexión WebSocket falló');
            });

            PUSHER.connection.bind('error', function(error) {
                console.error('❌ Error de WebSocket:', error);
            });

        }, 100);

    } catch (error) {
        console.error('💥 Error en configurarWebSocketNotificaciones:', error);
        console.error('Stack trace:', error.stack);
    }
}
```

## Cambios principales

| Optimización | Descripción |
|--------------|-------------|
| `setTimeout(..., 100)` | Difiere la conexión para no bloquear el render |
| `forceTLS: es_https` | Usa TLS automáticamente según el protocolo de la página |
| `enabledTransports` dinámico | Solo intenta el transporte correcto (ws o wss) |
| `activityTimeout: 30000` | Detecta conexiones inactivas en 30s |
| `pongTimeout: 10000` | Espera máximo 10s por respuesta del servidor |
| Timeout manual de 5s | Aborta la conexión si no conecta en 5 segundos |
| Suscripción en `connected` | Solo suscribe al canal después de estar conectado |

¿Quieres que aplique estos cambios al archivo?
